def immutable_guards(create, tables=("interview_plans", "interview_authorizations", "scheduling_responses", "recruiter_decisions")):
    dialect=op.get_bind().dialect.name
    for table in tables:
        for action in ("UPDATE","DELETE"):
            name=f"protect_{table}_{action.lower()}"
            condition="1=1" if action=="UPDATE" else "NOT EXISTS (SELECT 1 FROM organizations WHERE id=OLD.org_id AND is_demo=1)"
            pg="TRUE" if action=="UPDATE" else "NOT EXISTS (SELECT 1 FROM organizations WHERE id=OLD.org_id AND is_demo=TRUE)"
            if dialect=="sqlite":
                op.execute(f"DROP TRIGGER IF EXISTS {name}")
                if create:op.execute(f"CREATE TRIGGER {name} BEFORE {action} ON {table} WHEN {condition} BEGIN SELECT RAISE(ABORT, 'immutable history'); END")
            elif dialect=="postgresql":
                op.execute(f"DROP TRIGGER IF EXISTS {name} ON {table}")
                op.execute(f"DROP FUNCTION IF EXISTS {name}_fn()")
                if create:
                    op.execute(f"CREATE FUNCTION {name}_fn() RETURNS trigger AS $$ BEGIN IF {pg} THEN RAISE EXCEPTION 'immutable history'; END IF; RETURN {'NEW' if action!='DELETE' else 'OLD'}; END; $$ LANGUAGE plpgsql")
                    op.execute(f"CREATE TRIGGER {name} BEFORE {action} ON {table} FOR EACH ROW EXECUTE FUNCTION {name}_fn()")


